var t=`1111-kelupis`;var a=`world-1111`;var n=`BN`;var o=`southeast-asia`;var r=8;var l=289;var s={en:`Kelupis`,ua:`Келупіс`};var u={en:`Kelupis is a dish from Brunei prepared with glutinous rice, coconut milk, banana leaf. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Келупіс, страва кухні країни Бруней, яку готують із таких продуктів: клейкий рис, кокосове молоко, банановий лист. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Soak the measured rice or noodles in clean cool water for about 220 minutes, then drain and proceed to the specified cooking step.`,ua:`Замочіть зазначені рис або локшину в чистій прохолодній воді близько 220 хвилин, злийте і переходьте до подальшого готування.`,t:[`rice-soaking`],m:220,i:[[`glutinous-rice`,440,`g`],[`water`,900,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`coconut-milk`,270,`ml`],[`table-salt`,4,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:14,i:[[`banana-leaf`,8,`leaf`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 50 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 50 хвилин до готовності.`,t:[`steaming`],m:50,i:[]}];var c={slug:t,id:a,country:`BN`,region:o,servings:8,minutes:289,title:s,text:u,steps:d};export{n as country,c as default,a as id,l as minutes,o as region,r as servings,t as slug,d as steps,u as text,s as title};